<div class="col-xl-4"><section class="card location-editor directory-panel directory-editor" id="location-editor"><div class="card-header"><h2 class="card-title"><?= $editing?'Edit':'Add' ?> <?= e($singular[$kind]) ?></h2><?php if($editing): ?><a href="<?= e($formUrl) ?>" class="small">Cancel edit</a><?php endif; ?></div><div class="card-body">
<form method="post" action="<?= e($formUrl) ?>" data-directory-searchable><?= csrf() ?><input type="hidden" name="_action" value="location_save"><input type="hidden" name="kind" value="<?= e($kind) ?>">
<?php if($editing): ?><input type="hidden" name="location_id" value="<?= e($editing['id']) ?>"><input type="hidden" name="version" value="<?= e($record['version']??$editing['updated_at']) ?>"><div class="location-record-meta mb-3"><span>System ID <strong>#<?= e($editing['id']) ?></strong></span><span>Updated <?= e(date_display($editing['updated_at'],true)) ?></span></div><?php else: ?><p class="small text-secondary">A permanent system ID is assigned when saved.</p><?php endif; ?>
<?php if($kind!=='region'): ?><?php if($editing): ?><label class="form-label"><?= $kind==='constituency'?'Region':'Constituency' ?></label><p class="location-parent"><?= e($parentOptions[$editing[$parentKey]]??'') ?></p><p class="small text-secondary">Parent stays fixed to protect linked records.</p><?php else: ?><?= select_field('parent_id',$kind==='constituency'?'Region':'Constituency',[''=>'Choose a parent']+$parentOptions,$parentValue,true) ?><?php endif; ?><?php endif; ?>
<fieldset <?= (($kind==='polling_station'&&(!$stationCodesReady||!$sharedStationNamesReady))||($needsShortnameUpdate&&!$editing))?'disabled':'' ?>><?php if($kind==='polling_station'): ?><?= input('station_code','Official polling station ID',$record['station_code']??'','text',true,'maxlength="64" autocomplete="off" aria-describedby="station-code-help"') ?><p id="station-code-help" class="small text-secondary">Enter the official identifier exactly as issued, including leading zeros. Must be unique across all polling stations. Station names may be shared, including within the same constituency.</p><?php endif; ?><?= input('name','Full name',$record['name']??'','text',true,'maxlength="'.match($kind){'region'=>160,'constituency'=>180,'electoral_area'=>200,default=>250}.'" autocomplete="off"') ?>
<?php if($hasShortname): ?><?= input('shortname','Shortname / initials',$record['shortname']??'','text',true,'maxlength="24" pattern="[A-Za-z0-9][A-Za-z0-9._\-]{0,23}" autocomplete="off" autocapitalize="characters" aria-describedby="shortname-help"') ?>
<p id="shortname-help" class="small text-secondary">1–24 letters or numbers; dots, underscores and hyphens are allowed. Saved in uppercase. Must be unique <?= $kind==='region'?'among regions':'within the parent' ?>.</p><?php endif; ?>
<?php if($kind==='polling_station'): ?><p class="location-parent small">A new station belongs directly to its constituency. Assign its branch from the directory when ready.</p><?php endif; ?>
<button class="btn btn-primary w-100"><?= $editing?'Save changes':'Create '.$singular[$kind] ?></button></fieldset></form>
<?php if($kind==='polling_station'): ?><p class="small mt-3 mb-0"><a href="<?= e(url('station_imports',['parent_id'=>$parentValue])) ?>"><i class="bi bi-upload me-1" aria-hidden="true"></i>Upload multiple polling stations</a></p><?php endif; ?><?php if($editing): ?><hr><h3 class="h6">Recent activity</h3><?php if(!$history): ?><p class="small text-secondary mb-0">No recorded changes yet.</p><?php else: ?><ul class="location-history"><?php foreach($history as $event): ?><li><strong><?= e(match($event['action_code']){'location.created'=>'Location created','location.updated'=>'Details updated','station.branch_assigned'=>'Branch assignment changed',default=>label($event['action_code'])}) ?></strong><span><?= e($event['actor']??'System') ?> · <?= e(date_display($event['occurred_at'],true)) ?></span></li><?php endforeach; ?></ul><?php endif; ?><?php endif; ?>
</div></section><p class="small text-secondary mt-3">Location details can change without changing system IDs or disconnecting voters.</p></div>
